import{_ as a}from"./chunks/fleet-management.uZl2JoWp.js";import{_ as l,o as t,c as r,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const f=JSON.parse('{"title":"Στόλος και κατηγορίες οχημάτων","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/fleet-management.md","filePath":"el/plus/fleet-management.md"}'),o={name:"el/plus/fleet-management.md"};function n(s,e,h,p,c,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="στολος-και-κατηγοριες-οχηματων" tabindex="-1">Στόλος και κατηγορίες οχημάτων <a class="header-anchor" href="#στολος-και-κατηγοριες-οχηματων" aria-label="Permalink to &quot;Στόλος και κατηγορίες οχημάτων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>TransferBook+ v0.7.9: προσχέδιο ελεγμένο στον πηγαίο κώδικα. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις· δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/fleet-management.png"><img src="'+a+'" alt="Κατάλογος στόλου: εμπορικές κατηγορίες οχημάτων, διαθεσιμότητα, χωρητικότητα και εργαλεία διαχείρισης."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Κατάλογος στόλου: εμπορικές κατηγορίες οχημάτων, διαθεσιμότητα, χωρητικότητα και εργαλεία διαχείρισης.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή.</p><p>Διατηρήστε τα στοιχεία οχημάτων και τις χωρητικότητες που χρησιμοποιούνται κατά την ανάθεση.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένο περιβάλλον, επιβεβαιώστε εταιρεία και ρόλο και χρησιμοποιήστε συνθετικά στοιχεία για εκπαίδευση.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Στο Fleet &amp; Luxury Vehicles Management αναζητήστε πινακίδα, μάρκα/μοντέλο, οδηγό ή περιοχή. Φιλτράρετε ανά Available, On Trip, Maintenance ή Offline.</li><li>Με δικαίωμα διαχείρισης χρησιμοποιήστε Add Vehicle ή Edit Vehicle. Επιλέξτε περιοχή και κατηγορία και εισαγάγετε πραγματική πινακίδα, μοντέλο, έτος και χωρητικότητες επιβατών και αποσκευών.</li><li>Ελέγξτε τον ορισμό της κατηγορίας πριν την αποθήκευση. Επιβεβαιώστε τα στοιχεία και την κατάσταση. Για συγκεκριμένη διαδρομή χρησιμοποιήστε τη διαδικασία ανάθεσης κράτησης.</li></ol><h2 id="επαληθευση-και-αντιμετωπιση-προβληματων" tabindex="-1">Επαλήθευση και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#επαληθευση-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Επαλήθευση και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Η κατηγορία δεν είναι συγκεκριμένο όχημα. Μην αυξάνετε τεχνητά τη χωρητικότητα και μη θεωρείτε τη σύνδεση οδηγού απόδειξη ανάθεσης κράτησης. Ελέγξτε δικαιώματα και κατάσταση αρχειοθέτησης.</p><h2 id="σχετικοι-οδηγοι" tabindex="-1">Σχετικοί οδηγοί <a class="header-anchor" href="#σχετικοι-οδηγοι" aria-label="Permalink to &quot;Σχετικοί οδηγοί&quot;">​</a></h2><ul><li><a href="/el/plus/">Εγχειρίδιο χειριστή</a></li><li><a href="/el/plus/reservations.html">Κρατήσεις</a></li><li><a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a></li></ul>',16)])])}const _=l(o,[["render",n]]);export{f as __pageData,_ as default};
